        const head = `${p.title.split(" ·")[0]} · ${X[i] === "No hints" ? "no hints" : X[i] + " example" + (X[i] === "1" ? "" : "s")}`, vals = S.map(s => ({ color: s.color, value: pct(p[s.key][i]), name: s.short.toLowerCase() }));
